    x=dict(zip(K,p)); x["slug"]=re.sub(r"[^a-z0-9]+","-",x["name"].lower()).strip("-"); x["emoji"]={"Waves":"🌊","Tides":"🌗","Storms":"🌀","Climate":"🌡","Currents":"🔄","Biology":"🦠","Geology":"🌋"}[x["kind"]]
    out.append(x)
